-- Generated by pwc2dbt from PowerCenter mapping m_FL_JS_MARTS_CORE, target CUSTOMERS.

with

sq_stg_customers as (
    -- Source Qualifier SQ_STG_CUSTOMERS
    select
        stg_customers.customer_id,
        stg_customers.customer_name
    from {{ ref('stg_customers') }} as stg_customers
),

sq_stg_orders2 as (
    -- Source Qualifier SQ_STG_ORDERS2
    select
        stg_orders2.order_id,
        stg_orders2.customer_id,
        stg_orders2.location_id,
        stg_orders2.ordered_at_day,
        stg_orders2.subtotal_cents,
        stg_orders2.tax_paid_cents,
        stg_orders2.order_total_cents,
        stg_orders2.subtotal,
        stg_orders2.tax_paid,
        stg_orders2.order_total
    from {{ ref('stg_orders') }} as stg_orders2
),

agg_orders_by_customer as (
    -- Aggregator AGG_ORDERS_BY_CUSTOMER
    select
        sq_stg_orders2.customer_id,
        count(sq_stg_orders2.order_id) as lifetime_orders,
        min(sq_stg_orders2.ordered_at_day) as first_order_date,
        max(sq_stg_orders2.ordered_at_day) as last_order_date,
        sum(sq_stg_orders2.order_total) as lifetime_spend,
        sum(sq_stg_orders2.subtotal) as lifetime_spend_pretax,
        sum(sq_stg_orders2.tax_paid) as lifetime_tax_paid
    from sq_stg_orders2
    group by sq_stg_orders2.customer_id
),

jnr_customers_orders as (
    -- Joiner JNR_CUSTOMERS_ORDERS
    -- Master Outer Join (master sq_stg_customers, detail agg_orders_by_customer)
    select
        sq_stg_customers.customer_id,
        sq_stg_customers.customer_name,
        agg_orders_by_customer.lifetime_orders,
        agg_orders_by_customer.first_order_date,
        agg_orders_by_customer.last_order_date,
        agg_orders_by_customer.lifetime_spend,
        agg_orders_by_customer.lifetime_spend_pretax,
        agg_orders_by_customer.lifetime_tax_paid
    from agg_orders_by_customer
        left join sq_stg_customers
            on sq_stg_customers.customer_id = agg_orders_by_customer.customer_id
),

exp_customer_metrics as (
    -- Expression EXP_CUSTOMER_METRICS
    select
        jnr_customers_orders.customer_id,
        jnr_customers_orders.customer_name,
        coalesce(jnr_customers_orders.lifetime_orders, 0) as lifetime_orders_cl,
        jnr_customers_orders.first_order_date,
        jnr_customers_orders.last_order_date,
        coalesce(jnr_customers_orders.lifetime_spend, 0) as lifetime_spend_cl,
        coalesce(jnr_customers_orders.lifetime_spend_pretax, 0) as lifetime_spend_pretax_cl,
        coalesce(jnr_customers_orders.lifetime_tax_paid, 0) as lifetime_tax_paid_cl,
        case when coalesce(jnr_customers_orders.lifetime_orders, 0) > 1 then 'returning' else 'new' end as customer_type
    from jnr_customers_orders
)

select
    exp_customer_metrics.customer_id,
    exp_customer_metrics.customer_name,
    exp_customer_metrics.lifetime_orders_cl as lifetime_orders,
    exp_customer_metrics.first_order_date,
    exp_customer_metrics.last_order_date,
    exp_customer_metrics.lifetime_spend_cl as lifetime_spend,
    exp_customer_metrics.lifetime_spend_pretax_cl as lifetime_spend_pretax,
    exp_customer_metrics.lifetime_tax_paid_cl as lifetime_tax_paid,
    exp_customer_metrics.customer_type
from exp_customer_metrics
